#!/usr/bin/env python3
import argparse,hashlib,json,shutil
from pathlib import Path
import sys
import cv2,numpy as np
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from scripts.annotate_weld_boundaries import _draw_polyline,_draw_midpoint_reference,AnnotationState,display_scale
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--input',required=True);p.add_argument('--json',required=True);p.add_argument('--overlay',required=True);p.add_argument('--output',required=True);a=p.parse_args();inp=Path(a.input);jp=Path(a.json);op=Path(a.overlay);out=Path(a.output);im=cv2.imread(str(inp));d=json.loads(jp.read_text());h,w=im.shape[:2];assert [w,h]==[4096,3072] and d['image_width']==w and d['image_height']==h and d['input_sha256']==sha(inp)
 L=[(float(x['x']),float(x['y'])) for x in d['left_boundary_manual_points']];R=[(float(x['x']),float(x['y'])) for x in d['right_boundary_manual_points']];assert len(L)>=6 and len(R)>=6
 for q in L+R:assert np.isfinite(q).all() and 0<=q[0]<w and 0<=q[1]<h
 assert L==sorted(L,key=lambda q:(q[1],q[0])) and R==sorted(R,key=lambda q:(q[1],q[0]));y0=max(L[0][1],R[0][1]);y1=min(L[-1][1],R[-1][1]);ys=np.linspace(y0,y1,200);lx=np.interp(ys,[q[1] for q in L],[q[0] for q in L]);rx=np.interp(ys,[q[1] for q in R],[q[0] for q in R]);assert np.all(lx<rx)
 st=AnnotationState(L,R);regen=im.copy();_draw_polyline(regen,L,1,(255,0,0));_draw_polyline(regen,R,1,(0,255,0));_draw_midpoint_reference(regen,st,1);out.mkdir(parents=True,exist_ok=True);regenp=out/'regenerated_annotation_overlay.png';cv2.imwrite(str(regenp),regen);orig=cv2.imread(str(op));diff=cv2.absdiff(orig,regen);mask=np.any(diff>0,axis=2);ys2,xs=np.where(mask);report={'json_valid':True,'geometry_valid':True,'json_overlay_consistent':bool(orig.shape==regen.shape and not mask.any()),'original_overlay_sha256':sha(op),'regenerated_overlay_sha256':sha(regenp),'pixel_different_count':int(mask.sum()),'pixel_different_ratio':float(mask.mean()),'max_pixel_difference':int(diff.max()),'difference_bbox':None if not mask.any() else [int(xs.min()),int(ys2.min()),int(xs.max()),int(ys2.max())],'left_point_count':len(L),'right_point_count':len(R),'common_y_range':[y0,y1],'width_stats':{'min':float(np.min(rx-lx)),'p05':float(np.percentile(rx-lx,5)),'p50':float(np.percentile(rx-lx,50)),'p95':float(np.percentile(rx-lx,95)),'max':float(np.max(rx-lx))}}
 cv2.imwrite(str(out/'annotation_consistency_montage.png'),np.hstack([cv2.resize(orig,(683,512)),cv2.resize(regen,(683,512)),cv2.resize(diff,(683,512))]));report['montage_readable']=cv2.imread(str(out/'annotation_consistency_montage.png')) is not None
 if report['json_overlay_consistent']:
  v2=Path(a.output).parent/'s1_d7_manual_ground_truth_v2';v2.mkdir(exist_ok=True);shutil.copyfile(jp,v2/'seam_center_lit_quality_01_annotation_v2.json');shutil.copyfile(op,v2/'seam_center_lit_quality_01_annotation_overlay_v2.png');shutil.copyfile(regenp,v2/'regenerated_annotation_overlay.png');shutil.copyfile(out/'annotation_consistency_montage.png',v2/'annotation_consistency_montage.png');report['status']='frozen';manifest={'ground_truth_version':'s1_d7_v2','status':'frozen','human_overlay_approved':True,'human_approval_source':'user explicitly confirmed current overlay is completely usable','json_overlay_consistent':True,'input_image_absolute':str(inp.resolve()),'input_image_relative':str(inp.relative_to(Path(a.output).parents[1])),'input_sha256':sha(inp),'json_sha256':sha(jp),'json_semantic_sha256':hashlib.sha256(json.dumps(d,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest(),'overlay_sha256':sha(op),'left_point_count':len(L),'right_point_count':len(R),'common_y_range':[y0,y1],'old_annotation_sha256':'1e0bc8eaf78f40b442c6b63bcace915178127f8b3a86ad64ac26de3bb579f62d','old_annotation_available':False,'supersedes_old_annotation':True,'invalid_historical_conclusions':'invalid_due_to_missing_old_annotation','historical_algorithm_baselines':'may_remain_algorithmically_reproducible','d12_output_valid_for_final_conclusion':False};(v2/'ground_truth_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');report['v2_directory']=str(v2)
 else:report['status']='not_frozen'
 (out/'annotation_validation_report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
if __name__=='__main__':main()
